#pragma once

/* Prefix the vendored bzip2 symbols so a second bzip2 implementation, such as the system libbz2 or
 * lzbench's stock bzip2 codec, can be linked into the same binary. This is the bzip2 analogue of
 * zlib's Z_PREFIX. The header must be force-included before bzlib.h or bzlib_private.h. */

#ifndef LIBRAPIDARCHIVE_BZIP2_PREFIX
#define LIBRAPIDARCHIVE_BZIP2_PREFIX librapidarchive_bz2_
#endif

#define LIBRAPIDARCHIVE_BZIP2_CONCAT_(prefix, name) prefix##name
#define LIBRAPIDARCHIVE_BZIP2_CONCAT(prefix, name) LIBRAPIDARCHIVE_BZIP2_CONCAT_(prefix, name)

#define BZ2_blockSort LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, blockSort)
#define BZ2_bsInitWrite LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bsInitWrite)
#define BZ2_bzBuffToBuffCompress \
    LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzBuffToBuffCompress)
#define BZ2_bzBuffToBuffCompressWithCRC \
    LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzBuffToBuffCompressWithCRC)
#define BZ2_bzBuffToBuffDecompress \
    LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzBuffToBuffDecompress)
#define BZ2_bzCompress LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzCompress)
#define BZ2_bzCompressEnd LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzCompressEnd)
#define BZ2_bzCompressInit LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzCompressInit)
#define BZ2_bzDecompress LIBRAPIDARCHIVE_BZIP2_CONCAT(LIBRAPIDARCHIVE_BZIP2_PREFIX, bzDecompress)
